module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] C
);

    // RTL is combinational with no reset; sample behavior on clk.

    // The 5-bit output matches the zero-extended sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) C == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 is the XOR of the least-significant input bits.
    check_sum_bit0: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0])
    );

    // Bit 1 includes the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) C[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 includes the propagated carry from bits 1:0.
    check_sum_bit2: assert property (
        @(posedge clk) C[2] == (A[2] ^ B[2] ^
            ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // Bit 3 includes the propagated carry from bits 2:0.
    check_sum_bit3: assert property (
        @(posedge clk) C[3] == (A[3] ^ B[3] ^
            ((A[2] & B[2]) |
             ((A[2] ^ B[2]) &
              ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    // Carry out is the final carry of the ripple-adder chain.
    check_carry_out: assert property (
        @(posedge clk) C[4] == (
            (A[3] & B[3]) |
            ((A[3] ^ B[3]) &
             ((A[2] & B[2]) |
              ((A[2] ^ B[2]) &
               ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
        )
    );

    // Adding zero on A passes B through with no carry.
    check_zero_plus_b: assert property (
        @(posedge clk) (A == 4'b0000) |-> (C == {1'b0, B})
    );

    // Adding zero on B passes A through with no carry.
    check_a_plus_zero: assert property (
        @(posedge clk) (B == 4'b0000) |-> (C == {1'b0, A})
    );

    // The all-ones corner case produces decimal 30.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b1111)) |-> (C == 5'b11110)
    );

endmodule